-- Independently recomputed fail-closed guards. DDL is manual and implicitly commits.
SET @deps := (SELECT COUNT(*)=15 FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND ((table_name='supplementary_exam_periods' AND column_name IN ('supplementary_exam_period_id','status')) OR (table_name='supplementary_exam_offerings' AND column_name IN ('supplementary_exam_offering_id','supplementary_exam_period_id','academic_program_id','course_id')) OR (table_name='supplementary_exam_registrations' AND column_name IN ('supplementary_exam_registration_id','supplementary_exam_offering_id','student_course_registration_id','student_id','status','current_slot')) OR (table_name='student_course_results' AND column_name IN ('student_course_registration_id','practical_total')) OR (table_name='grading_policies' AND column_name='theoretical_max_mark')));
SET @engines := (SELECT COUNT(*)=9 FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_type='BASE TABLE' AND engine='InnoDB' AND table_name IN ('supplementary_exam_periods','supplementary_exam_period_events','supplementary_exam_offerings','supplementary_exam_offering_sources','supplementary_exam_offering_events','supplementary_exam_theoretical_deferrals','supplementary_exam_theoretical_deferral_events','supplementary_exam_registrations','supplementary_exam_registration_events'));
SET @roles := (SELECT COUNT(*)=2 FROM `alrowad_uni_rust`.`roles` WHERE role_code IN ('doctor_instructor','exam_officer') AND is_active=1);
SET @module := (SELECT COUNT(*)=1 FROM `alrowad_uni_rust`.`system_modules` WHERE module_code='exams' AND is_active=1);
SET @conflict := (SELECT COUNT(*) FROM information_schema.tables t WHERE t.table_schema='alrowad_uni_rust' AND t.table_name IN ('supplementary_exam_grader_assignments','supplementary_exam_grade_results','supplementary_exam_grade_submissions','supplementary_exam_grade_events') AND (t.table_type<>'BASE TABLE' OR t.engine<>'InnoDB')) + (SELECT COUNT(*) FROM information_schema.tables t WHERE t.table_schema='alrowad_uni_rust' AND t.table_name='supplementary_exam_grade_results' AND NOT EXISTS(SELECT 1 FROM information_schema.columns c WHERE c.table_schema=t.table_schema AND c.table_name=t.table_name AND c.column_name='supplementary_exam_registration_id'));
SET @apply_ready := @deps AND @engines AND @roles AND @module AND @conflict=0;
SET @before := (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_name IN ('supplementary_exam_grader_assignments','supplementary_exam_grade_results','supplementary_exam_grade_submissions','supplementary_exam_grade_events'));
SET @sql:=IF(@apply_ready,'CREATE TABLE IF NOT EXISTS `alrowad_uni_rust`.`supplementary_exam_grader_assignments` (`supplementary_exam_grader_assignment_id` INT NOT NULL AUTO_INCREMENT,`supplementary_exam_offering_id` INT NOT NULL,`faculty_member_id` INT NOT NULL,`current_slot` TINYINT NULL DEFAULT 1,`assigned_by_user_id` INT NOT NULL,`assigned_at` DATETIME NOT NULL,`ended_at` DATETIME NULL,`created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY (`supplementary_exam_grader_assignment_id`),UNIQUE KEY `uq_sega_offering_slot` (`supplementary_exam_offering_id`,`current_slot`),KEY `ix_sega_faculty_slot` (`faculty_member_id`,`current_slot`),CONSTRAINT `fk_sega_offering` FOREIGN KEY (`supplementary_exam_offering_id`) REFERENCES `alrowad_uni_rust`.`supplementary_exam_offerings` (`supplementary_exam_offering_id`),CONSTRAINT `fk_sega_faculty` FOREIGN KEY (`faculty_member_id`) REFERENCES `alrowad_uni_rust`.`faculty_members` (`faculty_member_id`),CONSTRAINT `fk_sega_actor` FOREIGN KEY (`assigned_by_user_id`) REFERENCES `alrowad_uni_rust`.`users` (`user_id`)) ENGINE=InnoDB COMMENT=''owned:supplementary-exam-grading-phase5''','SELECT ''BLOCKED''');PREPARE s FROM @sql;EXECUTE s;DEALLOCATE PREPARE s;
SET @sql:=IF(@apply_ready,'CREATE TABLE IF NOT EXISTS `alrowad_uni_rust`.`supplementary_exam_grade_results` (`supplementary_exam_grade_result_id` INT NOT NULL AUTO_INCREMENT,`supplementary_exam_registration_id` INT NOT NULL,`supplementary_exam_offering_id` INT NOT NULL,`student_course_registration_id` INT NOT NULL,`student_id` INT NOT NULL,`theoretical_mark` DECIMAL(5,2) NULL,`status` VARCHAR(24) NOT NULL DEFAULT ''draft'',`submission_version` INT NOT NULL DEFAULT 1,`last_edited_by_user_id` INT NOT NULL,`published_at` DATETIME NULL,`created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY (`supplementary_exam_grade_result_id`),UNIQUE KEY `uq_segr_registration` (`supplementary_exam_registration_id`),KEY `ix_segr_offering_status` (`supplementary_exam_offering_id`,`status`),CONSTRAINT `fk_segr_registration` FOREIGN KEY (`supplementary_exam_registration_id`) REFERENCES `alrowad_uni_rust`.`supplementary_exam_registrations` (`supplementary_exam_registration_id`),CONSTRAINT `fk_segr_offering` FOREIGN KEY (`supplementary_exam_offering_id`) REFERENCES `alrowad_uni_rust`.`supplementary_exam_offerings` (`supplementary_exam_offering_id`),CONSTRAINT `fk_segr_regular` FOREIGN KEY (`student_course_registration_id`) REFERENCES `alrowad_uni_rust`.`student_course_registrations` (`student_course_registration_id`),CONSTRAINT `fk_segr_student` FOREIGN KEY (`student_id`) REFERENCES `alrowad_uni_rust`.`students` (`student_id`),CONSTRAINT `fk_segr_editor` FOREIGN KEY (`last_edited_by_user_id`) REFERENCES `alrowad_uni_rust`.`users` (`user_id`)) ENGINE=InnoDB COMMENT=''owned:supplementary-exam-grading-phase5''','SELECT ''BLOCKED''');PREPARE s FROM @sql;EXECUTE s;DEALLOCATE PREPARE s;
SET @sql:=IF(@apply_ready,'CREATE TABLE IF NOT EXISTS `alrowad_uni_rust`.`supplementary_exam_grade_submissions` (`supplementary_exam_grade_submission_id` INT NOT NULL AUTO_INCREMENT,`supplementary_exam_offering_id` INT NOT NULL,`grader_assignment_id` INT NOT NULL,`submission_version` INT NOT NULL,`status` VARCHAR(24) NOT NULL,`submitted_by_user_id` INT NOT NULL,`submitted_at` DATETIME NOT NULL,`reviewed_by_user_id` INT NULL,`reviewed_at` DATETIME NULL,`review_reason` TEXT NULL,`published_by_user_id` INT NULL,`published_at` DATETIME NULL,`created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY (`supplementary_exam_grade_submission_id`),UNIQUE KEY `uq_segs_version` (`supplementary_exam_offering_id`,`submission_version`),CONSTRAINT `fk_segs_offering` FOREIGN KEY (`supplementary_exam_offering_id`) REFERENCES `alrowad_uni_rust`.`supplementary_exam_offerings` (`supplementary_exam_offering_id`),CONSTRAINT `fk_segs_assignment` FOREIGN KEY (`grader_assignment_id`) REFERENCES `alrowad_uni_rust`.`supplementary_exam_grader_assignments` (`supplementary_exam_grader_assignment_id`),CONSTRAINT `fk_segs_submitter` FOREIGN KEY (`submitted_by_user_id`) REFERENCES `alrowad_uni_rust`.`users` (`user_id`),CONSTRAINT `fk_segs_reviewer` FOREIGN KEY (`reviewed_by_user_id`) REFERENCES `alrowad_uni_rust`.`users` (`user_id`),CONSTRAINT `fk_segs_publisher` FOREIGN KEY (`published_by_user_id`) REFERENCES `alrowad_uni_rust`.`users` (`user_id`)) ENGINE=InnoDB COMMENT=''owned:supplementary-exam-grading-phase5''','SELECT ''BLOCKED''');PREPARE s FROM @sql;EXECUTE s;DEALLOCATE PREPARE s;
SET @sql:=IF(@apply_ready,'CREATE TABLE IF NOT EXISTS `alrowad_uni_rust`.`supplementary_exam_grade_events` (`supplementary_exam_grade_event_id` INT NOT NULL AUTO_INCREMENT,`supplementary_exam_grade_result_id` INT NOT NULL,`supplementary_exam_grade_submission_id` INT NULL,`event_type` VARCHAR(40) NOT NULL,`from_status` VARCHAR(24) NULL,`to_status` VARCHAR(24) NOT NULL,`submission_version` INT NOT NULL,`theoretical_mark` DECIMAL(5,2) NULL,`actor_user_id` INT NOT NULL,`notes` TEXT NULL,`created_at` DATETIME NOT NULL,PRIMARY KEY (`supplementary_exam_grade_event_id`),KEY `ix_sege_result_created` (`supplementary_exam_grade_result_id`,`created_at`),CONSTRAINT `fk_sege_result` FOREIGN KEY (`supplementary_exam_grade_result_id`) REFERENCES `alrowad_uni_rust`.`supplementary_exam_grade_results` (`supplementary_exam_grade_result_id`),CONSTRAINT `fk_sege_submission` FOREIGN KEY (`supplementary_exam_grade_submission_id`) REFERENCES `alrowad_uni_rust`.`supplementary_exam_grade_submissions` (`supplementary_exam_grade_submission_id`),CONSTRAINT `fk_sege_actor` FOREIGN KEY (`actor_user_id`) REFERENCES `alrowad_uni_rust`.`users` (`user_id`)) ENGINE=InnoDB COMMENT=''owned:supplementary-exam-grading-phase5''','SELECT ''BLOCKED''');PREPARE s FROM @sql;EXECUTE s;DEALLOCATE PREPARE s;
START TRANSACTION;
INSERT INTO `alrowad_uni_rust`.`permissions` (`permission_code`,`permission_name`,`module_id`,`is_active`,`created_at`,`updated_at`) SELECT x.code,x.name,m.module_id,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM (SELECT 'supplementary_exams.grades.view' code,'View supplementary grades' name UNION ALL SELECT 'supplementary_exams.grades.assign','Assign supplementary grader' UNION ALL SELECT 'supplementary_exams.grades.enter','Enter supplementary theoretical grades' UNION ALL SELECT 'supplementary_exams.grades.review','Review supplementary grades' UNION ALL SELECT 'supplementary_exams.grades.publish','Publish supplementary grades') x JOIN `alrowad_uni_rust`.`system_modules` m ON m.module_code='exams' WHERE @apply_ready AND NOT EXISTS(SELECT 1 FROM `alrowad_uni_rust`.`permissions` p WHERE p.permission_code=x.code);
INSERT INTO `alrowad_uni_rust`.`role_permissions` (`role_id`,`permission_id`,`granted_at`) SELECT r.role_id,p.permission_id,CURRENT_TIMESTAMP FROM `alrowad_uni_rust`.`roles` r JOIN `alrowad_uni_rust`.`permissions` p ON ((r.role_code='doctor_instructor' AND p.permission_code IN ('supplementary_exams.grades.view','supplementary_exams.grades.enter')) OR (r.role_code='exam_officer' AND p.permission_code IN ('supplementary_exams.grades.view','supplementary_exams.grades.assign','supplementary_exams.grades.enter','supplementary_exams.grades.review','supplementary_exams.grades.publish'))) WHERE @apply_ready AND NOT EXISTS(SELECT 1 FROM `alrowad_uni_rust`.`role_permissions` rp WHERE rp.role_id=r.role_id AND rp.permission_id=p.permission_id);
COMMIT;
SET @after := (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_name IN ('supplementary_exam_grader_assignments','supplementary_exam_grade_results','supplementary_exam_grade_submissions','supplementary_exam_grade_events'));
SELECT 'APPLY' report_section,IF(NOT @apply_ready,'BLOCKED',IF(@before=4,'ALREADY_APPLIED',IF(@after=4,'APPLIED','ROLLED_BACK'))) result;
